  "identity": {
    "name": "Courtside & Crown",
    "tagline": "Where Tradition Meets the Game.",
    "one_line_description": "Courtside & Crown is a heritage tennis academy website that showcases elite coaching programmes, club history, match fixtures, and news for players and families who value tradition, excellence, and community.",
