          "body": null,
          "items": [
            {
              "title": "Margaret T., Club Member since 1998",
              "description": "\"Courtside & Crown gave my daughter more than a backhand \u2014 it gave her confidence, discipline, and friendships that have lasted a lifetime.\"",
              "metadata": {}
