    {
      "slug": "club",
      "title": "The Club",
      "role": "overview",
      "goal": "Tell the full story of Courtside & Crown \u2014 its history, coaching staff, membership tiers, and facilities \u2014 so that prospective members have everything they need to commit.",
      "meta_description": "Learn about Courtside & Crown Tennis Academy \u2014 our century of history, expert coaching team, membership options, and world-class facilities.",
      "sections": [
        {
          "id": "club-section-1",
          "type": "page_header",
          "intent": "Set the tone for the Club page as a proud, authoritative account of who we are and what we stand for.",
          "eyebrow": "Our Story",
          "headline": "A Club Built on Courts and Character",
          "subheadline": "Since 1923, Courtside & Crown has shaped players and people in equal measure.",
          "body": "What began as a small grass-court club in the heart of the county has grown into one of the region's most respected tennis academies. Our walls carry the portraits of champions; our courts carry the footsteps of thousands of members whose lives were changed by the game.",
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "club-section-1-asset-1",
              "kind": "illustration",
              "subject": "A vintage-style timeline banner showing key milestones of the club from 1923 to present, with small iconographic markers for each decade.",
              "purpose": "Visual anchor for the club history narrative that communicates longevity and prestige in a single glance.",
              "quantity": 1,
              "used_by": [
                "club-section-1"
              ]
            }
          ]
        },
        {
          "id": "club-section-2",
          "type": "timeline",
          "intent": "Chronicle the academy's most significant milestones to deepen emotional investment and reinforce the heritage brand story.",
          "eyebrow": "Our History",
          "headline": "One Hundred Years, One Unbroken Tradition",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "1923 \u2014 Founded",
              "description": "Courtside & Crown opens with four grass courts and thirty founding members on the Harrowfield estate.",
              "metadata": {}
            },
            {
              "title": "1951 \u2014 First County Title",
              "description": "Our men's first team claims the county championship for the first time, cementing our competitive reputation.",
              "metadata": {}
            },
            {
              "title": "1974 \u2014 Clubhouse Expansion",
              "description": "The iconic red-brick clubhouse is extended, adding a viewing terrace, lounge, and junior changing facilities.",
              "metadata": {}
            },
            {
              "title": "1989 \u2014 Junior Academy Launched",
              "description": "A dedicated junior coaching pathway is introduced, producing three national-ranked juniors within a decade.",
              "metadata": {}
            },
            {
              "title": "2003 \u2014 Indoor Courts Added",
              "description": "Two all-weather indoor courts ensure year-round play and open the academy to a wider community.",
              "metadata": {}
            },
            {
              "title": "2023 \u2014 Centenary Season",
              "description": "Courtside & Crown celebrates 100 years with a centenary tournament, alumni weekend, and the launch of our scholarship programme.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "club-section-3",
          "type": "item_grid",
          "intent": "Introduce the coaching team with credibility and warmth, so prospective members trust the people who will guide their development.",
          "eyebrow": "Our Coaches",
          "headline": "Guided by the Best in the Game",
          "subheadline": "Every coach at Courtside & Crown holds LTA Level 3 or above certification and brings a passion for player development.",
          "body": null,
          "items": [
            {
              "title": "Head Coach \u2014 William Ashford",
              "description": "Former ATP Challenger circuit player and LTA Level 5 Master Professional. William leads the performance squad and oversees all coaching standards.",
              "metadata": {
                "credential": "LTA Level 5 Master Professional",
                "speciality": "Performance & Tactics"
              }
            },
            {
              "title": "Junior Development Coach \u2014 Sasha Merritt",
              "description": "Specialist in 8\u201316 junior development with a decade of experience producing county-ranked players from grassroots beginnings.",
              "metadata": {
                "credential": "LTA Level 4",
                "speciality": "Junior Development"
              }
            },
            {
              "title": "Adult & Beginner Coach \u2014 Fiona Calloway",
              "description": "Renowned for her patient, encouraging approach, Fiona runs all adult beginner and improver programmes with infectious enthusiasm.",
              "metadata": {
                "credential": "LTA Level 3",
                "speciality": "Adult Beginners & Improvers"
              }
            },
            {
              "title": "Strength & Conditioning \u2014 Marcus Obi",
              "description": "A certified S&C specialist who works with our competitive squads on physical conditioning, injury prevention, and athletic longevity.",
              "metadata": {
                "credential": "UKSCA Accredited",
                "speciality": "Athletic Performance"
              }
            }
          ],
          "ctas": [
            {
              "label": "Enquire About Coaching",
              "target_page": "contact"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "club-section-4",
          "type": "pricing",
          "intent": "Present membership tiers clearly so prospective members can self-select the right option and take the next step without friction.",
          "eyebrow": "Membership",
          "headline": "Find Your Place at the Club",
          "subheadline": "Every membership includes full court access, club events, and the right to wear the Courtside & Crown badge with pride.",
          "body": null,
          "items": [
            {
              "title": "Junior Membership",
              "description": "For players aged 8\u201317. Includes group coaching sessions, junior squad access, and inter-club match entry.",
              "metadata": {
                "price": "\u00a3195 / year",
                "highlight": "Most Popular for Families"
              }
            },
            {
              "title": "Adult Social Membership",
              "description": "For recreational adult players. Full court booking access, club nights, and social tournaments year-round.",
              "metadata": {
                "price": "\u00a3320 / year",
                "highlight": ""
              }
            },
            {
              "title": "Performance Membership",
              "description": "For competitive adults and advanced juniors. Includes priority coaching slots, performance squad sessions, and match analysis.",
              "metadata": {
                "price": "\u00a3580 / year",
                "highlight": "Best for Competitors"
              }
            },
            {
              "title": "Family Membership",
              "description": "Up to two adults and three juniors under one roof. Full access to all programmes and a dedicated family match day experience.",
              "metadata": {
                "price": "\u00a3895 / year",
                "highlight": "Best Value"
              }
            }
          ],
          "ctas": [
            {
              "label": "Apply for Membership",
              "target_page": "contact"
            }
          ],
          "asset_ideas": [
            {
              "id": "club-section-4-asset-1",
              "kind": "icon",
              "subject": "A set of four membership badge icons \u2014 a laurel sprig for junior, a racket for social, a trophy for performance, and a family crest shield for family \u2014 each in a classic medallion style.",
              "purpose": "Visual differentiators for each membership tier card that reinforce the heritage aesthetic and make the pricing grid scannable.",
              "quantity": 1,
              "used_by": [
                "club-section-4"
              ]
            }
          ]
        },
        {
          "id": "club-section-5",
          "type": "feature_grid",
          "intent": "Highlight the physical facilities of the academy to reassure prospective members that the infrastructure matches the reputation.",
          "eyebrow": "Our Facilities",
          "headline": "Courts Worthy of Champions",
          "subheadline": "Eight courts, a storied clubhouse, and everything a serious player needs to thrive.",
          "body": null,
          "items": [
            {
              "title": "4 Grass Courts",
              "description": "Meticulously maintained to Wimbledon-standard specifications, open from May through September.",
              "metadata": {}
            },
            {
              "title": "2 All-Weather Hard Courts",
              "description": "Available twelve months a year for training, club matches, and private hire.",
              "metadata": {}
            },
            {
              "title": "2 Indoor Courts",
              "description": "Climate-controlled and floodlit, ensuring no session is ever cancelled by the British weather.",
              "metadata": {}
            },
            {
              "title": "Heritage Clubhouse",
              "description": "A warm, members-only space featuring a lounge, bar, trophy room, and viewing terrace overlooking the grass courts.",
              "metadata": {}
            },
            {
              "title": "Ball Machine Studio",
              "description": "A dedicated solo practice bay equipped with a professional ball machine for drilling at any time.",
              "metadata": {}
            },
            {
              "title": "Fitness Suite",
              "description": "A compact on-site gym tailored for tennis-specific conditioning, used by our performance squad daily.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        }
      ]
    },
