          "eyebrow": "Latest Stories",
          "headline": "Fresh from the Courts",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Centenary Scholarship Fund Now Open for Applications",
              "description": "In honour of our 100th year, the Courtside & Crown Foundation is offering three full junior memberships and coaching bursaries to talented players from underserved backgrounds. Applications close 31 October.",
              "metadata": {
                "category": "Club Announcement",
                "date": "10 September 2024"
              }
            },
            {
              "title": "James Rutherford Named in County Under-18 Squad",
              "description": "Courtside & Crown Junior A captain James Rutherford has been selected for the county Under-18 representative squad following an outstanding summer season. A proud moment for the whole club.",
              "metadata": {
                "category": "Player Achievement",
                "date": "6 September 2024"
              }
            },
            {
              "title": "New Ball Machine Studio Opens This Weekend",
              "description": "Our newly installed ball machine practice studio is open to all members from Saturday 14 September. Book a solo session through the members portal or contact the club office.",
              "metadata": {
                "category": "Facilities",
                "date": "3 September 2024"
              }
            },
