input.content:
/* =========================================================
   Courtside & Crown — Heritage Tennis Academy
   Design System: heritage_classic | layout_family: card_grid
   ========================================================= */

/* ---------- Fonts ---------- */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;0,700;0,800;1,400;1,600&family=Source+Serif+4:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Montserrat:wght@400;500;600;700&display=swap');

/* ---------- Tokens ---------- */
:root {
  --crown-ivory: #F5F0E8;
  --courtside-navy: #1B2A4A;
  --burgundy-crest: #7D1D3F;
  --champ-gold: #B8962E;
  --forest-court: #2D5016;
  --antique-linen: #EAE3D2;
  --slate-mist: #D6D9E0;
  --ink-smoke: #4A4E5A;

  --font-display: 'Playfair Display', 'Garamond', 'Times New Roman', serif;
  --font-body: 'Source Serif 4', 'Georgia', 'Cambria', serif;
  --font-accent: 'Montserrat', 'Helvetica Neue', Arial, sans-serif;

  --max-width: 1280px;
  --content-width: 1120px;

  --shadow-card: 0 2px 12px rgba(27, 42, 74, 0.08);
  --shadow-card-hover: 0 8px 24px rgba(27, 42, 74, 0.14);

  --transition: 200ms ease;
}

/* ---------- Reset ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--ink-smoke);
  background: var(--crown-ivory);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--burgundy-crest);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--champ-gold);
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

p {
  margin: 0 0 1em;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 700;
  margin: 0;
  color: var(--courtside-navy);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

ul, ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ---------- Layout helpers ---------- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 80px;
}

.content {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
}

.section {
  padding: 96px 0;
  position: relative;
}

.section--ivory   { background: var(--crown-ivory); }
.section--linen   { background: var(--antique-linen); }
.section--navy    { background: var(--courtside-navy); color: var(--crown-ivory); }
.section--navy h1,
.section--navy h2,
.section--navy h3 { color: var(--crown-ivory); }

.section--narrow .content {
  max-width: 760px;
}

/* ---------- Typography utility ---------- */
.eyebrow {
  font-family: var(--font-accent);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--champ-gold);
  margin: 0 0 14px;
}

.eyebrow--burgundy { color: var(--burgundy-crest); }

.section-headline {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 44px);
  color: var(--courtside-navy);
  margin: 0 0 16px;
}

.section--navy .section-headline { color: var(--crown-ivory); }

.section-subhead {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 18px;
  color: var(--ink-smoke);
  line-height: 1.65;
  max-width: 600px;
  margin: 0 auto 8px;
}

.section--navy .section-subhead {
  color: rgba(245, 240, 232, 0.85);
}

.section-header {
  text-align: center;
  margin-bottom: 56px;
}

.section-header--left {
  text-align: left;
  max-width: var(--content-width);
  margin: 0 auto 40px;
}

/* Ornamental divider — gold line with diamond lozenges */
.ornament {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 12px 0 14px;
}

.ornament .rule {
  display: block;
  width: 60px;
  height: 1px;
  background: var(--champ-gold);
}

.ornament .lozenge {
  width: 8px;
  height: 8px;
  background: var(--champ-gold);
  transform: rotate(45deg);
  display: block;
}

.ornament--wide .rule { width: 80px; }
.ornament--narrow .rule { width: 40px; }

.section-header--left .ornament { margin-left: 0; margin-right: 0; }

/* Section divider rule (full-width thin gold) */
.section-divider {
  height: 1px;
  background: var(--champ-gold);
  opacity: 0.55;
  width: 100%;
  margin: 0;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 14px 36px;
  border: 2px solid transparent;
  border-radius: 0;
  text-decoration: none;
  cursor: pointer;
  transition: all var(--transition);
  line-height: 1;
  white-space: nowrap;
}

.btn--primary {
  background: var(--burgundy-crest);
  color: var(--crown-ivory);
  border-color: var(--burgundy-crest);
}

.btn--primary:hover {
  background: #5e1530;
  border-color: var(--champ-gold);
  color: var(--crown-ivory);
}

.btn--outline {
  background: transparent;
  border-color: var(--crown-ivory);
  color: var(--crown-ivory);
}

.btn--outline:hover {
  background: var(--crown-ivory);
  color: var(--courtside-navy);
}

.btn--outline-navy {
  background: transparent;
  border-color: var(--courtside-navy);
  color: var(--courtside-navy);
}

.btn--outline-navy:hover {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
}

.btn--gold {
  background: var(--champ-gold);
  color: var(--courtside-navy);
  border-color: var(--champ-gold);
}

.btn--gold:hover {
  background: #cda94a;
  border-color: var(--courtside-navy);
}

.btn-row {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 32px;
}

/* ---------- Header / Navigation ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--courtside-navy);
  border-bottom: 1px solid rgba(184, 150, 46, 0.4);
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.18);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 88px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  color: var(--crown-ivory);
}

.brand:hover { color: var(--crown-ivory); }

.brand-mark {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
}

.brand-text { line-height: 1.05; }

.brand-name {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--crown-ivory);
  display: block;
}

.brand-tag {
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--champ-gold);
  display: block;
  margin-top: 2px;
}

.primary-nav {
  display: flex;
  gap: 36px;
  align-items: center;
}

.primary-nav a {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--crown-ivory);
  position: relative;
  padding: 8px 0;
}

.primary-nav a:hover { color: var(--champ-gold); }

.primary-nav a.is-active {
  color: var(--champ-gold);
}

.primary-nav a.is-active::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -2px;
  height: 2px;
  background: var(--champ-gold);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  color: var(--crown-ivory);
}
.nav-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--crown-ivory);
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--courtside-navy);
  color: var(--antique-linen);
  padding: 72px 0 32px;
  position: relative;
}

.site-footer::before {
  content: "";
  display: block;
  height: 1px;
  background: var(--champ-gold);
  opacity: 0.5;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-grid h4 {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 11px;
  color: var(--champ-gold);
  margin-bottom: 18px;
  font-weight: 600;
}

.footer-grid p,
.footer-grid li {
  font-size: 14px;
  color: rgba(245, 240, 232, 0.78);
  line-height: 1.7;
}

.footer-grid li { margin-bottom: 8px; }

.footer-grid a {
  color: rgba(245, 240, 232, 0.78);
}

.footer-grid a:hover { color: var(--champ-gold); }

.footer-mark {
  width: 56px;
  height: 56px;
  margin-bottom: 16px;
}

.footer-brand-name {
  font-family: var(--font-display);
  color: var(--crown-ivory);
  font-size: 24px;
  margin: 0 0 8px;
}

.footer-tag {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--champ-gold);
  margin: 0 0 16px;
}

.footer-bottom {
  border-top: 1px solid rgba(214, 217, 224, 0.18);
  padding-top: 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(245, 240, 232, 0.6);
}

/* ============================================================
   HERO (home-section-1)
   ============================================================ */
.hero {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 80px 80px;
  position: relative;
  overflow: hidden;
}

.hero::after {
  /* subtle vignette */
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 50%, rgba(0,0,0,0.35) 100%);
  pointer-events: none;
}

.hero > * { position: relative; z-index: 1; }

.hero-emblem {
  width: 160px;
  height: 160px;
  margin-bottom: 24px;
}

.hero-eyebrow {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--champ-gold);
  font-weight: 500;
  margin-bottom: 16px;
}

.hero-headline {
  font-family: var(--font-display);
  font-size: clamp(40px, 6vw, 72px);
  color: var(--crown-ivory);
  letter-spacing: -0.02em;
  max-width: 820px;
  margin: 16px auto;
  font-weight: 700;
  line-height: 1.08;
}

.hero-sub {
  font-family: var(--font-body);
  font-size: 20px;
  line-height: 1.7;
  color: var(--slate-mist);
  max-width: 620px;
  margin: 24px auto 0;
}

.hero .btn-row { margin-top: 40px; }

.scroll-indicator {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--champ-gold);
  animation: floatY 2.4s ease-in-out infinite;
}

@keyframes floatY {
  0%, 100% { transform: translate(-50%, 0); }
  50% { transform: translate(-50%, 8px); }
}

/* ============================================================
   STATS BAND
   ============================================================ */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
  max-width: 1100px;
  margin: 0 auto;
}

.stat-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 32px 24px;
  text-align: center;
  box-shadow: var(--shadow-card);
}

.section--linen .stat-card { background: var(--crown-ivory); }
.section--ivory .stat-card { background: var(--crown-ivory); }

.stat-figure {
  font-family: var(--font-accent);
  font-size: clamp(34px, 4.4vw, 52px);
  font-weight: 700;
  color: var(--champ-gold);
  letter-spacing: 0.02em;
  line-height: 1;
}

.stat-figure--display {
  /* alt treatment: serif version for fixtures */
  font-family: var(--font-display);
  color: var(--courtside-navy);
}

.stat-rule {
  width: 40px;
  height: 2px;
  background: var(--champ-gold);
  margin: 12px auto;
}

.stat-desc {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink-smoke);
}

/* Fixtures: scoreboard accent stat card */
.stat-card--scoreboard {
  position: relative;
  padding-top: 32px;
}
.stat-card--scoreboard::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--champ-gold);
}

/* ============================================================
   FEATURE CARDS GRID
   ============================================================ */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  max-width: 1100px;
  margin: 0 auto;
}

.feature-card {
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 40px 32px;
  text-align: center;
  position: relative;
  box-shadow: var(--shadow-card);
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
}

.section--linen .feature-card,
.section--linen .pillar-card { background: var(--crown-ivory); }

.feature-card:hover {
  background: var(--crown-ivory);
  border-color: var(--champ-gold);
  transform: translateY(-2px);
}

.feature-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 0;
  background: var(--champ-gold);
  transition: height var(--transition);
}

.feature-card:hover::before { height: 3px; }

.icon-badge {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  background: var(--courtside-navy);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--champ-gold);
}

.feature-card h3,
.pillar-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  margin: 0 0 12px;
  font-weight: 700;
}

.mini-rule {
  width: 32px;
  height: 1px;
  background: var(--champ-gold);
  margin: 12px auto 16px;
}

.feature-card p,
.pillar-card p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.7;
  margin: 0;
}

.feature-card .icon-badge svg { width: 28px; height: 28px; }

/* Facility cards: line-icon variant */
.facility-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 6px;
  padding: 28px;
  text-align: center;
  position: relative;
  box-shadow: var(--shadow-card);
  transition: all var(--transition);
}

.facility-card:hover {
  box-shadow: 0 4px 16px rgba(27,42,74,0.10);
  border-top-color: var(--champ-gold);
  transform: translateY(-2px);
}
.facility-card:hover::before { height: 3px; }
.facility-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 0;
  background: var(--champ-gold);
  transition: height var(--transition);
  border-radius: 6px 6px 0 0;
}

.facility-card .line-icon {
  width: 48px; height: 48px;
  margin: 0 auto;
  color: var(--courtside-navy);
}

.facility-card h3 { margin-top: 12px; font-size: 19px; }

/* ============================================================
   TESTIMONIALS
   ============================================================ */
.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  max-width: 1100px;
  margin: 0 auto;
}

.testimonial-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 40px 36px 32px;
  position: relative;
  box-shadow: 0 2px 12px rgba(27, 42, 74, 0.07);
}

.testimonial-card .quote-mark {
  font-family: var(--font-display);
  font-size: 72px;
  color: var(--champ-gold);
  line-height: 0.6;
  margin-bottom: 8px;
  font-style: italic;
}

.testimonial-card blockquote {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 17px;
  color: var(--courtside-navy);
  line-height: 1.75;
  margin: 0 0 20px;
}

.testimonial-card .attribution-rule {
  width: 40px;
  height: 1px;
  background: var(--slate-mist);
  margin: 16px 0;
}

.testimonial-card cite {
  font-family: var(--font-accent);
  font-style: normal;
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

/* "Terrace" italic flourish */
.italic-flourish { font-style: italic; }

/* ============================================================
   CTA SECTION (textured)
   ============================================================ */
.cta-section {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  text-align: center;
  padding: 104px 0;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("assets/court-pattern.svg");
  background-repeat: repeat;
  background-size: 240px 240px;
  opacity: 0.10;
  pointer-events: none;
}

.cta-section > * { position: relative; z-index: 1; }

.cta-section .eyebrow { color: var(--champ-gold); }

.cta-section h2 {
  font-family: var(--font-display);
  color: var(--crown-ivory);
  font-size: clamp(34px, 4.4vw, 52px);
  margin: 12px 0 20px;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.15;
}

.cta-section p {
  font-family: var(--font-body);
  font-size: 19px;
  color: var(--slate-mist);
  max-width: 600px;
  margin: 0 auto 24px;
  line-height: 1.7;
}

/* ============================================================
   PAGE HEADER (non-home)
   ============================================================ */
.page-header {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  text-align: center;
  padding: 120px 0 96px;
  position: relative;
  overflow: hidden;
}

.page-header::before {
  /* radial vignette */
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 50%, rgba(0,0,0,0.30) 100%);
  pointer-events: none;
}

.page-header .crest-flourish {
  width: 36px;
  height: 36px;
  margin: 0 auto 18px;
  color: var(--champ-gold);
}

.page-header h1 {
  font-family: var(--font-display);
  font-size: clamp(36px, 5vw, 56px);
  color: var(--crown-ivory);
  margin: 12px 0 20px;
  letter-spacing: -0.01em;
  line-height: 1.15;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
}

.page-header .lede {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 20px;
  color: rgba(234, 227, 210, 0.92);
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.6;
}

.page-header .body {
  font-family: var(--font-body);
  font-size: 17px;
  color: var(--slate-mist);
  max-width: 680px;
  margin: 24px auto 0;
}

.page-header .timeline-banner {
  margin-top: 56px;
  width: 80%;
  max-width: 900px;
  opacity: 0.85;
}

/* ============================================================
   TIMELINE (club-section-2)
   ============================================================ */
.timeline {
  position: relative;
  max-width: 980px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0;
  left: 50%;
  width: 2px;
  background: var(--champ-gold);
  transform: translateX(-1px);
}

.timeline-entry {
  position: relative;
  width: 50%;
  padding: 20px 36px;
  box-sizing: border-box;
}

.timeline-entry:nth-child(odd) {
  left: 0;
  text-align: right;
}

.timeline-entry:nth-child(even) {
  left: 50%;
}

.timeline-entry .node {
  position: absolute;
  top: 36px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--courtside-navy);
  border: 2px solid var(--champ-gold);
  z-index: 2;
}

.timeline-entry:nth-child(odd) .node { right: -7px; }
.timeline-entry:nth-child(even) .node { left: -7px; }

.timeline-entry .connector {
  position: absolute;
  top: 42px;
  width: 24px;
  height: 1px;
  background: var(--champ-gold);
}

.timeline-entry:nth-child(odd) .connector { right: 0; }
.timeline-entry:nth-child(even) .connector { left: 0; }

.timeline-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 24px;
  box-shadow: 0 2px 8px rgba(27,42,74,0.08);
  display: inline-block;
  text-align: left;
  max-width: 340px;
}

.timeline-card h4 {
  font-family: var(--font-display);
  font-size: 20px;
  color: var(--courtside-navy);
  margin: 0 0 8px;
  font-weight: 700;
}

.timeline-card .year {
  color: var(--champ-gold);
  font-weight: 700;
}

.timeline-card p {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.7;
  color: var(--ink-smoke);
  margin: 0;
}

/* ============================================================
   COACHES GRID (club-section-3)
   ============================================================ */
.coach-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.coach-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 6px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.coach-card::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: 0;
  width: 0;
  background: var(--burgundy-crest);
  transition: width var(--transition);
  border-radius: 6px 0 0 6px;
}

.coach-card:hover { background: var(--antique-linen); }
.coach-card:hover::before { width: 3px; }

.coach-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--antique-linen);
  border: 2px solid var(--champ-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 26px;
  color: var(--courtside-navy);
  font-weight: 700;
  margin-bottom: 16px;
}

.coach-role {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

.coach-name {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  margin: 4px 0 12px;
  font-weight: 700;
}

.coach-desc {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.7;
  color: var(--ink-smoke);
  text-align: left;
  margin: 0 0 18px;
}

.tag-pill {
  display: inline-block;
  padding: 5px 12px;
  border-radius: 999px;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 600;
}

.tag-pill--forest {
  background: var(--forest-court);
  color: var(--crown-ivory);
}

.tag-pill--gold {
  background: var(--champ-gold);
  color: var(--courtside-navy);
}

.tag-pill--burgundy {
  background: var(--burgundy-crest);
  color: var(--crown-ivory);
}

.tag-pill--navy {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
}

.coach-speciality {
  margin-top: 8px;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--champ-gold);
}

/* ============================================================
   PRICING CARDS (club-section-4)
   ============================================================ */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--crown-ivory);
  border: 1px solid var(--champ-gold);
  border-radius: 6px;
  padding: 32px 28px;
  position: relative;
  text-align: center;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  box-shadow: 0 8px 24px rgba(0,0,0,0.18);
  border-width: 2px;
  padding: 31px 27px;
}

.ribbon {
  position: absolute;
  top: 14px;
  right: -8px;
  background: var(--burgundy-crest);
  color: var(--crown-ivory);
  font-family: var(--font-accent);
  text-transform: uppercase;
  font-size: 9px;
  letter-spacing: 0.12em;
  font-weight: 600;
  padding: 6px 14px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.18);
}

.ribbon::after {
  content: "";
  position: absolute;
  right: 0; bottom: -6px;
  width: 0; height: 0;
  border-top: 6px solid #4d1226;
  border-right: 8px solid transparent;
}

.pricing-medallion {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
}

.pricing-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  font-weight: 700;
  margin: 0 0 12px;
}

.price-figure {
  font-family: var(--font-accent);
  font-size: 28px;
  font-weight: 700;
  color: var(--champ-gold);
  letter-spacing: 0.02em;
  line-height: 1;
}

.price-suffix {
  font-family: var(--font-accent);
  font-size: 12px;
  color: var(--ink-smoke);
  margin-left: 4px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.pricing-divider {
  height: 1px;
  background: var(--slate-mist);
  margin: 18px 0 16px;
}

.pricing-card p {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.7;
  color: var(--ink-smoke);
  text-align: left;
  margin: 0;
}

/* ============================================================
   FACILITIES (club-section-5)
   ============================================================ */
.facility-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

/* ============================================================
   FIXTURES PAGE
   ============================================================ */
.fixture-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.fixture-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-left: 3px solid var(--burgundy-crest);
  border-radius: 4px;
  padding: 28px;
  transition: all var(--transition);
  box-shadow: 0 2px 10px rgba(27,42,74,0.06);
}

.fixture-card:hover {
  background: var(--antique-linen);
  box-shadow: var(--shadow-card-hover);
}

.fixture-card .meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.fixture-card h3 {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  margin: 4px 0 8px;
  font-weight: 700;
}

.fixture-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--ink-smoke);
  line-height: 1.6;
  margin: 0;
}

/* Result-coded cards */
.result-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-left: 3px solid var(--slate-mist);
  border-radius: 4px;
  padding: 28px;
  transition: all var(--transition);
  box-shadow: 0 2px 10px rgba(27,42,74,0.06);
}

.result-card:hover { background: var(--antique-linen); box-shadow: var(--shadow-card-hover); }

.result-card.result-win   { border-left-color: var(--forest-court); }
.result-card.result-draw  { border-left-color: var(--champ-gold); }
.result-card.result-loss  { border-left-color: var(--burgundy-crest); }

.result-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 6px;
}

.result-pill-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.result-score {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  color: var(--courtside-navy);
}

.result-date {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

.result-card h3 {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  margin: 10px 0 8px;
  font-weight: 700;
}

.result-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--ink-smoke);
  line-height: 1.6;
  margin: 0;
}

/* Squad performance chart */
.chart-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 32px;
  margin: 56px auto 0;
  max-width: 960px;
}

.chart-card h4 {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--courtside-navy);
  font-weight: 600;
  margin: 0 0 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.chart-card h4::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--slate-mist);
}

.chart-row {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 16px;
  align-items: center;
  margin-bottom: 14px;
}

.chart-row:last-child { margin-bottom: 0; }

.chart-label {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--courtside-navy);
  font-weight: 600;
}

.chart-bar {
  display: flex;
  height: 22px;
  border-radius: 2px;
  overflow: hidden;
  background: var(--antique-linen);
}

.chart-bar .seg-w { background: var(--burgundy-crest); }
.chart-bar .seg-d { background: var(--champ-gold); }
.chart-bar .seg-l { background: var(--ink-smoke); }

.chart-bar span {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.1em;
  font-weight: 700;
  color: var(--crown-ivory);
}

.chart-legend {
  margin-top: 24px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

.legend-swatch {
  display: inline-block;
  width: 12px; height: 12px;
  margin-right: 8px;
  vertical-align: middle;
}

/* ============================================================
   NEWS PAGE
   ============================================================ */
.masthead {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  padding: 120px 0 100px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.masthead::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("assets/linen-grain.svg");
  background-size: 240px 240px;
  background-repeat: repeat;
  opacity: 0.05;
  pointer-events: none;
}

.masthead > * { position: relative; z-index: 1; }

.masthead-banner {
  width: min(520px, 92%);
  margin: 0 auto 24px;
}

.masthead h1 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 56px);
  color: var(--crown-ivory);
  margin: 16px auto 18px;
  max-width: 880px;
  letter-spacing: -0.01em;
  line-height: 1.15;
}

.masthead .lede {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 20px;
  color: rgba(245, 240, 232, 0.65);
  max-width: 580px;
  margin: 0 auto;
  line-height: 1.6;
}

/* News article cards */
.lead-article {
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-left: 6px solid var(--burgundy-crest);
  border-radius: 4px;
  padding: 40px;
  max-width: 900px;
  margin: 0 auto 32px;
  position: relative;
}

.article-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  flex-wrap: wrap;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.article-meta .cat {
  font-weight: 600;
}

.article-meta .cat--forest { color: var(--forest-court); }
.article-meta .cat--gold { color: var(--champ-gold); }
.article-meta .cat--navy { color: var(--courtside-navy); }
.article-meta .cat--burgundy { color: var(--burgundy-crest); }

.article-meta .dot {
  width: 4px; height: 4px;
  border-radius: 50%;
  background: var(--slate-mist);
  display: inline-block;
}

.article-meta .date {
  color: var(--ink-smoke);
}

.lead-article h3 {
  font-family: var(--font-display);
  font-size: 26px;
  color: var(--courtside-navy);
  margin: 0 0 12px;
  line-height: 1.25;
  font-weight: 700;
}

.lead-article p {
  font-family: var(--font-body);
  font-size: 17px;
  color: var(--ink-smoke);
  line-height: 1.7;
  margin: 0 0 20px;
}

.read-more {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--burgundy-crest);
  font-weight: 600;
}

.read-more:hover { color: var(--champ-gold); }

.article-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}

.article-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 28px;
  box-shadow: 0 2px 12px rgba(27,42,74,0.08);
  transition: all var(--transition);
}

.article-card:hover {
  background: var(--antique-linen);
  box-shadow: var(--shadow-card-hover);
}

.article-card h3 {
  font-family: var(--font-display);
  font-size: 20px;
  color: var(--courtside-navy);
  margin: 0 0 10px;
  font-weight: 700;
  line-height: 1.3;
}

.article-card p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.65;
  margin: 0 0 16px;
}

/* Featured story (news-section-3) */
.featured-story {
  background: var(--antique-linen);
  padding: 96px 0;
  position: relative;
}

.frieze {
  display: block;
  width: 100%;
  height: 44px;
  background-image: url("assets/frieze.svg");
  background-repeat: repeat-x;
  background-size: auto 44px;
  background-position: center;
}

.featured-story .content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
  padding: 24px 32px;
}

.featured-story h2 {
  font-family: var(--font-display);
  font-size: clamp(30px, 4vw, 46px);
  color: var(--courtside-navy);
  margin: 16px 0 18px;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.featured-story .featured-sub {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 19px;
  color: var(--ink-smoke);
  line-height: 1.7;
  max-width: 620px;
  margin: 0 auto 24px;
}

.featured-story .featured-body {
  font-family: var(--font-body);
  font-size: 18px;
  color: var(--courtside-navy);
  line-height: 1.75;
  text-align: left;
  margin: 32px 0;
}

/* Category browse grid */
.category-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  max-width: 960px;
  margin: 0 auto;
}

.category-tile {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 32px;
  position: relative;
  transition: all var(--transition);
  cursor: pointer;
  display: block;
  color: inherit;
}

.category-tile::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--champ-gold);
  border-radius: 4px 4px 0 0;
}

.category-tile:hover {
  background: var(--antique-linen);
  box-shadow: 0 4px 16px rgba(27,42,74,0.15);
  transform: translateY(-2px);
}

.category-tile:hover::before { background: var(--burgundy-crest); }

.category-tile .cat-icon {
  width: 28px; height: 28px;
  color: var(--champ-gold);
  margin-bottom: 18px;
}

.category-tile h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  margin: 0 0 8px;
  font-weight: 700;
}

.category-tile p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--ink-smoke);
  line-height: 1.6;
  margin: 0 0 16px;
}

.cat-count {
  display: inline-block;
  background: var(--antique-linen);
  color: var(--champ-gold);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 600;
  padding: 5px 12px;
  border-radius: 999px;
}

/* ============================================================
   CONTACT PAGE
   ============================================================ */
.contact-block {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: start;
  max-width: 1120px;
  margin: 0 auto;
}

.contact-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.contact-item {
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-radius: 16px;
  padding: 20px 24px;
  display: grid;
  grid-template-columns: 36px 1fr;
  gap: 16px;
  align-items: start;
  transition: all var(--transition);
  position: relative;
}

.contact-item::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: 0;
  width: 0;
  background: var(--burgundy-crest);
  transition: width var(--transition);
  border-radius: 16px 0 0 16px;
}

.contact-item:hover { background: #ddd5bf; }
.contact-item:hover::before { width: 3px; }

.contact-icon {
  width: 28px; height: 28px;
  color: var(--champ-gold);
  margin-top: 4px;
}

.contact-item h4 {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--courtside-navy);
  font-weight: 600;
  margin: 0 0 4px;
}

.contact-item p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.55;
  margin: 0;
}

.map-frame {
  background: var(--antique-linen);
  padding: 14px;
  border: 2px solid var(--champ-gold);
  border-radius: 4px;
  position: relative;
}

.map-frame::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid var(--champ-gold);
  pointer-events: none;
}

.map-frame svg { display: block; width: 100%; height: auto; background: var(--crown-ivory); }

.map-caption {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-smoke);
  text-align: center;
  margin-top: 12px;
}

/* Enquiry feature grid */
.enquiry-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.enquiry-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 2px 8px rgba(27,42,74,0.07);
  transition: all var(--transition);
}

.enquiry-card:hover {
  background: var(--antique-linen);
  border-color: var(--champ-gold);
  border-width: 2px;
  padding: 31px;
}

.enquiry-card:hover h3 { color: var(--burgundy-crest); }

.enquiry-badge {
  width: 40px;
  height: 40px;
  margin-bottom: 16px;
  color: var(--champ-gold);
}

.enquiry-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  margin: 0 0 10px;
  font-weight: 700;
  transition: color var(--transition);
}

.enquiry-card p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.65;
  margin: 0 0 16px;
}

.enquiry-email {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--burgundy-crest);
  font-weight: 600;
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}

.enquiry-email:hover {
  color: var(--burgundy-crest);
  border-bottom-color: var(--champ-gold);
}

/* FAQ */
.faq-icons-row {
  display: flex;
  gap: 32px;
  justify-content: center;
  margin-bottom: 36px;
}

.faq-icons-row .seal {
  width: 36px; height: 36px;
  color: var(--champ-gold);
}

.faq-list {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-left: 3px solid var(--slate-mist);
  border-radius: 4px;
  overflow: hidden;
  transition: background var(--transition), border-color var(--transition);
}

.faq-item[open] {
  background: var(--antique-linen);
  border-left-color: var(--burgundy-crest);
}

.faq-item summary {
  list-style: none;
  cursor: pointer;
  padding: 18px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  font-weight: 700;
}

.faq-item summary::-webkit-details-marker { display: none; }

.faq-item summary::after {
  content: "+";
  font-family: var(--font-accent);
  font-size: 22px;
  color: var(--champ-gold);
  font-weight: 400;
  transition: transform var(--transition);
}

.faq-item[open] summary::after { content: "−"; }

.faq-item .answer {
  padding: 0 24px 20px;
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.7;
  margin: 0;
}

/* ============================================================
   PILLAR / FEATURE GRID generic 3-up (used in feature_grid sections)
   ============================================================ */
.pillar-card {
  text-align: center;
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 40px 32px;
  position: relative;
  box-shadow: var(--shadow-card);
  transition: all var(--transition);
}

.pillar-card:hover {
  background: var(--crown-ivory);
  border-color: var(--champ-gold);
  transform: translateY(-2px);
}

.pillar-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 0;
  background: var(--champ-gold);
  border-radius: 4px 4px 0 0;
  transition: height var(--transition);
}

.pillar-card:hover::before { height: 3px; }

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1100px) {
  .container { padding: 0 40px; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid,
  .testimonial-grid { grid-template-columns: repeat(2, 1fr); }
  .coach-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
  .facility-grid { grid-template-columns: repeat(2, 1fr); }
  .article-grid { grid-template-columns: 1fr; }
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .contact-block { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .fixture-list { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .section { padding: 64px 0; }
  .hero { min-height: 90vh; padding: 80px 20px 60px; }
  .hero-emblem { width: 120px; height: 120px; }
  .hero-headline { font-size: 36px; }
  .hero-sub { font-size: 16px; }
  .stats-grid,
  .feature-grid,
  .testimonial-grid,
  .coach-grid,
  .pricing-grid,
  .facility-grid,
  .category-grid,
  .enquiry-grid { grid-template-columns: 1fr; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }

  .primary-nav {
    display: none;
    position: absolute;
    top: 88px;
    right: 0;
    left: 0;
    background: var(--courtside-navy);
    flex-direction: column;
    padding: 24px;
    gap: 18px;
    border-bottom: 1px solid rgba(184,150,46,0.4);
  }
  .primary-nav.is-open { display: flex; }
  .nav-toggle { display: flex; }

  .timeline::before { left: 16px; transform: none; }
  .timeline-entry,
  .timeline-entry:nth-child(odd),
  .timeline-entry:nth-child(even) {
    width: 100%;
    left: 0;
    text-align: left;
    padding-left: 44px;
    padding-right: 0;
  }
  .timeline-entry:nth-child(odd) .node,
  .timeline-entry:nth-child(even) .node { left: 9px; right: auto; }
  .timeline-entry:nth-child(odd) .connector,
  .timeline-entry:nth-child(even) .connector { left: 16px; right: auto; }

  .chart-row { grid-template-columns: 1fr; gap: 6px; }

  .btn-row { flex-direction: column; align-items: stretch; }
  .btn { width: 100%; }

  .lead-article { padding: 28px; }
  .featured-story .content { padding: 16px 16px; }
  .faq-icons-row { display: none; }
}

tool_use_result.content:
/* =========================================================
   Courtside & Crown — Heritage Tennis Academy
   Design System: heritage_classic | layout_family: card_grid
   ========================================================= */

/* ---------- Fonts ---------- */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;0,700;0,800;1,400;1,600&family=Source+Serif+4:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Montserrat:wght@400;500;600;700&display=swap');

/* ---------- Tokens ---------- */
:root {
  --crown-ivory: #F5F0E8;
  --courtside-navy: #1B2A4A;
  --burgundy-crest: #7D1D3F;
  --champ-gold: #B8962E;
  --forest-court: #2D5016;
  --antique-linen: #EAE3D2;
  --slate-mist: #D6D9E0;
  --ink-smoke: #4A4E5A;

  --font-display: 'Playfair Display', 'Garamond', 'Times New Roman', serif;
  --font-body: 'Source Serif 4', 'Georgia', 'Cambria', serif;
  --font-accent: 'Montserrat', 'Helvetica Neue', Arial, sans-serif;

  --max-width: 1280px;
  --content-width: 1120px;

  --shadow-card: 0 2px 12px rgba(27, 42, 74, 0.08);
  --shadow-card-hover: 0 8px 24px rgba(27, 42, 74, 0.14);

  --transition: 200ms ease;
}

/* ---------- Reset ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--ink-smoke);
  background: var(--crown-ivory);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--burgundy-crest);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--champ-gold);
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

p {
  margin: 0 0 1em;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 700;
  margin: 0;
  color: var(--courtside-navy);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

ul, ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ---------- Layout helpers ---------- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 80px;
}

.content {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
}

.section {
  padding: 96px 0;
  position: relative;
}

.section--ivory   { background: var(--crown-ivory); }
.section--linen   { background: var(--antique-linen); }
.section--navy    { background: var(--courtside-navy); color: var(--crown-ivory); }
.section--navy h1,
.section--navy h2,
.section--navy h3 { color: var(--crown-ivory); }

.section--narrow .content {
  max-width: 760px;
}

/* ---------- Typography utility ---------- */
.eyebrow {
  font-family: var(--font-accent);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--champ-gold);
  margin: 0 0 14px;
}

.eyebrow--burgundy { color: var(--burgundy-crest); }

.section-headline {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 44px);
  color: var(--courtside-navy);
  margin: 0 0 16px;
}

.section--navy .section-headline { color: var(--crown-ivory); }

.section-subhead {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 18px;
  color: var(--ink-smoke);
  line-height: 1.65;
  max-width: 600px;
  margin: 0 auto 8px;
}

.section--navy .section-subhead {
  color: rgba(245, 240, 232, 0.85);
}

.section-header {
  text-align: center;
  margin-bottom: 56px;
}

.section-header--left {
  text-align: left;
  max-width: var(--content-width);
  margin: 0 auto 40px;
}

/* Ornamental divider — gold line with diamond lozenges */
.ornament {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 12px 0 14px;
}

.ornament .rule {
  display: block;
  width: 60px;
  height: 1px;
  background: var(--champ-gold);
}

.ornament .lozenge {
  width: 8px;
  height: 8px;
  background: var(--champ-gold);
  transform: rotate(45deg);
  display: block;
}

.ornament--wide .rule { width: 80px; }
.ornament--narrow .rule { width: 40px; }

.section-header--left .ornament { margin-left: 0; margin-right: 0; }

/* Section divider rule (full-width thin gold) */
.section-divider {
  height: 1px;
  background: var(--champ-gold);
  opacity: 0.55;
  width: 100%;
  margin: 0;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 14px 36px;
  border: 2px solid transparent;
  border-radius: 0;
  text-decoration: none;
  cursor: pointer;
  transition: all var(--transition);
  line-height: 1;
  white-space: nowrap;
}

.btn--primary {
  background: var(--burgundy-crest);
  color: var(--crown-ivory);
  border-color: var(--burgundy-crest);
}

.btn--primary:hover {
  background: #5e1530;
  border-color: var(--champ-gold);
  color: var(--crown-ivory);
}

.btn--outline {
  background: transparent;
  border-color: var(--crown-ivory);
  color: var(--crown-ivory);
}

.btn--outline:hover {
  background: var(--crown-ivory);
  color: var(--courtside-navy);
}

.btn--outline-navy {
  background: transparent;
  border-color: var(--courtside-navy);
  color: var(--courtside-navy);
}

.btn--outline-navy:hover {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
}

.btn--gold {
  background: var(--champ-gold);
  color: var(--courtside-navy);
  border-color: var(--champ-gold);
}

.btn--gold:hover {
  background: #cda94a;
  border-color: var(--courtside-navy);
}

.btn-row {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 32px;
}

/* ---------- Header / Navigation ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--courtside-navy);
  border-bottom: 1px solid rgba(184, 150, 46, 0.4);
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.18);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 88px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  color: var(--crown-ivory);
}

.brand:hover { color: var(--crown-ivory); }

.brand-mark {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
}

.brand-text { line-height: 1.05; }

.brand-name {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--crown-ivory);
  display: block;
}

.brand-tag {
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--champ-gold);
  display: block;
  margin-top: 2px;
}

.primary-nav {
  display: flex;
  gap: 36px;
  align-items: center;
}

.primary-nav a {
  font-family: var(--font-accent);
  font-weight: 500;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--crown-ivory);
  position: relative;
  padding: 8px 0;
}

.primary-nav a:hover { color: var(--champ-gold); }

.primary-nav a.is-active {
  color: var(--champ-gold);
}

.primary-nav a.is-active::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -2px;
  height: 2px;
  background: var(--champ-gold);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  color: var(--crown-ivory);
}
.nav-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--crown-ivory);
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--courtside-navy);
  color: var(--antique-linen);
  padding: 72px 0 32px;
  position: relative;
}

.site-footer::before {
  content: "";
  display: block;
  height: 1px;
  background: var(--champ-gold);
  opacity: 0.5;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-grid h4 {
  font-family: var(--font-accent);
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 11px;
  color: var(--champ-gold);
  margin-bottom: 18px;
  font-weight: 600;
}

.footer-grid p,
.footer-grid li {
  font-size: 14px;
  color: rgba(245, 240, 232, 0.78);
  line-height: 1.7;
}

.footer-grid li { margin-bottom: 8px; }

.footer-grid a {
  color: rgba(245, 240, 232, 0.78);
}

.footer-grid a:hover { color: var(--champ-gold); }

.footer-mark {
  width: 56px;
  height: 56px;
  margin-bottom: 16px;
}

.footer-brand-name {
  font-family: var(--font-display);
  color: var(--crown-ivory);
  font-size: 24px;
  margin: 0 0 8px;
}

.footer-tag {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--champ-gold);
  margin: 0 0 16px;
}

.footer-bottom {
  border-top: 1px solid rgba(214, 217, 224, 0.18);
  padding-top: 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(245, 240, 232, 0.6);
}

/* ============================================================
   HERO (home-section-1)
   ============================================================ */
.hero {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 80px 80px;
  position: relative;
  overflow: hidden;
}

.hero::after {
  /* subtle vignette */
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 50%, rgba(0,0,0,0.35) 100%);
  pointer-events: none;
}

.hero > * { position: relative; z-index: 1; }

.hero-emblem {
  width: 160px;
  height: 160px;
  margin-bottom: 24px;
}

.hero-eyebrow {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--champ-gold);
  font-weight: 500;
  margin-bottom: 16px;
}

.hero-headline {
  font-family: var(--font-display);
  font-size: clamp(40px, 6vw, 72px);
  color: var(--crown-ivory);
  letter-spacing: -0.02em;
  max-width: 820px;
  margin: 16px auto;
  font-weight: 700;
  line-height: 1.08;
}

.hero-sub {
  font-family: var(--font-body);
  font-size: 20px;
  line-height: 1.7;
  color: var(--slate-mist);
  max-width: 620px;
  margin: 24px auto 0;
}

.hero .btn-row { margin-top: 40px; }

.scroll-indicator {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--champ-gold);
  animation: floatY 2.4s ease-in-out infinite;
}

@keyframes floatY {
  0%, 100% { transform: translate(-50%, 0); }
  50% { transform: translate(-50%, 8px); }
}

/* ============================================================
   STATS BAND
   ============================================================ */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
  max-width: 1100px;
  margin: 0 auto;
}

.stat-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 32px 24px;
  text-align: center;
  box-shadow: var(--shadow-card);
}

.section--linen .stat-card { background: var(--crown-ivory); }
.section--ivory .stat-card { background: var(--crown-ivory); }

.stat-figure {
  font-family: var(--font-accent);
  font-size: clamp(34px, 4.4vw, 52px);
  font-weight: 700;
  color: var(--champ-gold);
  letter-spacing: 0.02em;
  line-height: 1;
}

.stat-figure--display {
  /* alt treatment: serif version for fixtures */
  font-family: var(--font-display);
  color: var(--courtside-navy);
}

.stat-rule {
  width: 40px;
  height: 2px;
  background: var(--champ-gold);
  margin: 12px auto;
}

.stat-desc {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink-smoke);
}

/* Fixtures: scoreboard accent stat card */
.stat-card--scoreboard {
  position: relative;
  padding-top: 32px;
}
.stat-card--scoreboard::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--champ-gold);
}

/* ============================================================
   FEATURE CARDS GRID
   ============================================================ */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  max-width: 1100px;
  margin: 0 auto;
}

.feature-card {
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 40px 32px;
  text-align: center;
  position: relative;
  box-shadow: var(--shadow-card);
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
}

.section--linen .feature-card,
.section--linen .pillar-card { background: var(--crown-ivory); }

.feature-card:hover {
  background: var(--crown-ivory);
  border-color: var(--champ-gold);
  transform: translateY(-2px);
}

.feature-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 0;
  background: var(--champ-gold);
  transition: height var(--transition);
}

.feature-card:hover::before { height: 3px; }

.icon-badge {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  background: var(--courtside-navy);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--champ-gold);
}

.feature-card h3,
.pillar-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  margin: 0 0 12px;
  font-weight: 700;
}

.mini-rule {
  width: 32px;
  height: 1px;
  background: var(--champ-gold);
  margin: 12px auto 16px;
}

.feature-card p,
.pillar-card p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.7;
  margin: 0;
}

.feature-card .icon-badge svg { width: 28px; height: 28px; }

/* Facility cards: line-icon variant */
.facility-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 6px;
  padding: 28px;
  text-align: center;
  position: relative;
  box-shadow: var(--shadow-card);
  transition: all var(--transition);
}

.facility-card:hover {
  box-shadow: 0 4px 16px rgba(27,42,74,0.10);
  border-top-color: var(--champ-gold);
  transform: translateY(-2px);
}
.facility-card:hover::before { height: 3px; }
.facility-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 0;
  background: var(--champ-gold);
  transition: height var(--transition);
  border-radius: 6px 6px 0 0;
}

.facility-card .line-icon {
  width: 48px; height: 48px;
  margin: 0 auto;
  color: var(--courtside-navy);
}

.facility-card h3 { margin-top: 12px; font-size: 19px; }

/* ============================================================
   TESTIMONIALS
   ============================================================ */
.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  max-width: 1100px;
  margin: 0 auto;
}

.testimonial-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 40px 36px 32px;
  position: relative;
  box-shadow: 0 2px 12px rgba(27, 42, 74, 0.07);
}

.testimonial-card .quote-mark {
  font-family: var(--font-display);
  font-size: 72px;
  color: var(--champ-gold);
  line-height: 0.6;
  margin-bottom: 8px;
  font-style: italic;
}

.testimonial-card blockquote {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 17px;
  color: var(--courtside-navy);
  line-height: 1.75;
  margin: 0 0 20px;
}

.testimonial-card .attribution-rule {
  width: 40px;
  height: 1px;
  background: var(--slate-mist);
  margin: 16px 0;
}

.testimonial-card cite {
  font-family: var(--font-accent);
  font-style: normal;
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

/* "Terrace" italic flourish */
.italic-flourish { font-style: italic; }

/* ============================================================
   CTA SECTION (textured)
   ============================================================ */
.cta-section {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  text-align: center;
  padding: 104px 0;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("assets/court-pattern.svg");
  background-repeat: repeat;
  background-size: 240px 240px;
  opacity: 0.10;
  pointer-events: none;
}

.cta-section > * { position: relative; z-index: 1; }

.cta-section .eyebrow { color: var(--champ-gold); }

.cta-section h2 {
  font-family: var(--font-display);
  color: var(--crown-ivory);
  font-size: clamp(34px, 4.4vw, 52px);
  margin: 12px 0 20px;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.15;
}

.cta-section p {
  font-family: var(--font-body);
  font-size: 19px;
  color: var(--slate-mist);
  max-width: 600px;
  margin: 0 auto 24px;
  line-height: 1.7;
}

/* ============================================================
   PAGE HEADER (non-home)
   ============================================================ */
.page-header {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  text-align: center;
  padding: 120px 0 96px;
  position: relative;
  overflow: hidden;
}

.page-header::before {
  /* radial vignette */
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 50%, rgba(0,0,0,0.30) 100%);
  pointer-events: none;
}

.page-header .crest-flourish {
  width: 36px;
  height: 36px;
  margin: 0 auto 18px;
  color: var(--champ-gold);
}

.page-header h1 {
  font-family: var(--font-display);
  font-size: clamp(36px, 5vw, 56px);
  color: var(--crown-ivory);
  margin: 12px 0 20px;
  letter-spacing: -0.01em;
  line-height: 1.15;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
}

.page-header .lede {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 20px;
  color: rgba(234, 227, 210, 0.92);
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.6;
}

.page-header .body {
  font-family: var(--font-body);
  font-size: 17px;
  color: var(--slate-mist);
  max-width: 680px;
  margin: 24px auto 0;
}

.page-header .timeline-banner {
  margin-top: 56px;
  width: 80%;
  max-width: 900px;
  opacity: 0.85;
}

/* ============================================================
   TIMELINE (club-section-2)
   ============================================================ */
.timeline {
  position: relative;
  max-width: 980px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0;
  left: 50%;
  width: 2px;
  background: var(--champ-gold);
  transform: translateX(-1px);
}

.timeline-entry {
  position: relative;
  width: 50%;
  padding: 20px 36px;
  box-sizing: border-box;
}

.timeline-entry:nth-child(odd) {
  left: 0;
  text-align: right;
}

.timeline-entry:nth-child(even) {
  left: 50%;
}

.timeline-entry .node {
  position: absolute;
  top: 36px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--courtside-navy);
  border: 2px solid var(--champ-gold);
  z-index: 2;
}

.timeline-entry:nth-child(odd) .node { right: -7px; }
.timeline-entry:nth-child(even) .node { left: -7px; }

.timeline-entry .connector {
  position: absolute;
  top: 42px;
  width: 24px;
  height: 1px;
  background: var(--champ-gold);
}

.timeline-entry:nth-child(odd) .connector { right: 0; }
.timeline-entry:nth-child(even) .connector { left: 0; }

.timeline-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 24px;
  box-shadow: 0 2px 8px rgba(27,42,74,0.08);
  display: inline-block;
  text-align: left;
  max-width: 340px;
}

.timeline-card h4 {
  font-family: var(--font-display);
  font-size: 20px;
  color: var(--courtside-navy);
  margin: 0 0 8px;
  font-weight: 700;
}

.timeline-card .year {
  color: var(--champ-gold);
  font-weight: 700;
}

.timeline-card p {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.7;
  color: var(--ink-smoke);
  margin: 0;
}

/* ============================================================
   COACHES GRID (club-section-3)
   ============================================================ */
.coach-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.coach-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 6px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.coach-card::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: 0;
  width: 0;
  background: var(--burgundy-crest);
  transition: width var(--transition);
  border-radius: 6px 0 0 6px;
}

.coach-card:hover { background: var(--antique-linen); }
.coach-card:hover::before { width: 3px; }

.coach-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--antique-linen);
  border: 2px solid var(--champ-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 26px;
  color: var(--courtside-navy);
  font-weight: 700;
  margin-bottom: 16px;
}

.coach-role {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

.coach-name {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  margin: 4px 0 12px;
  font-weight: 700;
}

.coach-desc {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.7;
  color: var(--ink-smoke);
  text-align: left;
  margin: 0 0 18px;
}

.tag-pill {
  display: inline-block;
  padding: 5px 12px;
  border-radius: 999px;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 600;
}

.tag-pill--forest {
  background: var(--forest-court);
  color: var(--crown-ivory);
}

.tag-pill--gold {
  background: var(--champ-gold);
  color: var(--courtside-navy);
}

.tag-pill--burgundy {
  background: var(--burgundy-crest);
  color: var(--crown-ivory);
}

.tag-pill--navy {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
}

.coach-speciality {
  margin-top: 8px;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--champ-gold);
}

/* ============================================================
   PRICING CARDS (club-section-4)
   ============================================================ */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--crown-ivory);
  border: 1px solid var(--champ-gold);
  border-radius: 6px;
  padding: 32px 28px;
  position: relative;
  text-align: center;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  box-shadow: 0 8px 24px rgba(0,0,0,0.18);
  border-width: 2px;
  padding: 31px 27px;
}

.ribbon {
  position: absolute;
  top: 14px;
  right: -8px;
  background: var(--burgundy-crest);
  color: var(--crown-ivory);
  font-family: var(--font-accent);
  text-transform: uppercase;
  font-size: 9px;
  letter-spacing: 0.12em;
  font-weight: 600;
  padding: 6px 14px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.18);
}

.ribbon::after {
  content: "";
  position: absolute;
  right: 0; bottom: -6px;
  width: 0; height: 0;
  border-top: 6px solid #4d1226;
  border-right: 8px solid transparent;
}

.pricing-medallion {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
}

.pricing-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  font-weight: 700;
  margin: 0 0 12px;
}

.price-figure {
  font-family: var(--font-accent);
  font-size: 28px;
  font-weight: 700;
  color: var(--champ-gold);
  letter-spacing: 0.02em;
  line-height: 1;
}

.price-suffix {
  font-family: var(--font-accent);
  font-size: 12px;
  color: var(--ink-smoke);
  margin-left: 4px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.pricing-divider {
  height: 1px;
  background: var(--slate-mist);
  margin: 18px 0 16px;
}

.pricing-card p {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.7;
  color: var(--ink-smoke);
  text-align: left;
  margin: 0;
}

/* ============================================================
   FACILITIES (club-section-5)
   ============================================================ */
.facility-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

/* ============================================================
   FIXTURES PAGE
   ============================================================ */
.fixture-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.fixture-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-left: 3px solid var(--burgundy-crest);
  border-radius: 4px;
  padding: 28px;
  transition: all var(--transition);
  box-shadow: 0 2px 10px rgba(27,42,74,0.06);
}

.fixture-card:hover {
  background: var(--antique-linen);
  box-shadow: var(--shadow-card-hover);
}

.fixture-card .meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.fixture-card h3 {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  margin: 4px 0 8px;
  font-weight: 700;
}

.fixture-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--ink-smoke);
  line-height: 1.6;
  margin: 0;
}

/* Result-coded cards */
.result-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-left: 3px solid var(--slate-mist);
  border-radius: 4px;
  padding: 28px;
  transition: all var(--transition);
  box-shadow: 0 2px 10px rgba(27,42,74,0.06);
}

.result-card:hover { background: var(--antique-linen); box-shadow: var(--shadow-card-hover); }

.result-card.result-win   { border-left-color: var(--forest-court); }
.result-card.result-draw  { border-left-color: var(--champ-gold); }
.result-card.result-loss  { border-left-color: var(--burgundy-crest); }

.result-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 6px;
}

.result-pill-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.result-score {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  color: var(--courtside-navy);
}

.result-date {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

.result-card h3 {
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  margin: 10px 0 8px;
  font-weight: 700;
}

.result-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--ink-smoke);
  line-height: 1.6;
  margin: 0;
}

/* Squad performance chart */
.chart-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 32px;
  margin: 56px auto 0;
  max-width: 960px;
}

.chart-card h4 {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--courtside-navy);
  font-weight: 600;
  margin: 0 0 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.chart-card h4::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--slate-mist);
}

.chart-row {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 16px;
  align-items: center;
  margin-bottom: 14px;
}

.chart-row:last-child { margin-bottom: 0; }

.chart-label {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--courtside-navy);
  font-weight: 600;
}

.chart-bar {
  display: flex;
  height: 22px;
  border-radius: 2px;
  overflow: hidden;
  background: var(--antique-linen);
}

.chart-bar .seg-w { background: var(--burgundy-crest); }
.chart-bar .seg-d { background: var(--champ-gold); }
.chart-bar .seg-l { background: var(--ink-smoke); }

.chart-bar span {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.1em;
  font-weight: 700;
  color: var(--crown-ivory);
}

.chart-legend {
  margin-top: 24px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-smoke);
}

.legend-swatch {
  display: inline-block;
  width: 12px; height: 12px;
  margin-right: 8px;
  vertical-align: middle;
}

/* ============================================================
   NEWS PAGE
   ============================================================ */
.masthead {
  background: var(--courtside-navy);
  color: var(--crown-ivory);
  padding: 120px 0 100px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.masthead::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("assets/linen-grain.svg");
  background-size: 240px 240px;
  background-repeat: repeat;
  opacity: 0.05;
  pointer-events: none;
}

.masthead > * { position: relative; z-index: 1; }

.masthead-banner {
  width: min(520px, 92%);
  margin: 0 auto 24px;
}

.masthead h1 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 56px);
  color: var(--crown-ivory);
  margin: 16px auto 18px;
  max-width: 880px;
  letter-spacing: -0.01em;
  line-height: 1.15;
}

.masthead .lede {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 20px;
  color: rgba(245, 240, 232, 0.65);
  max-width: 580px;
  margin: 0 auto;
  line-height: 1.6;
}

/* News article cards */
.lead-article {
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-left: 6px solid var(--burgundy-crest);
  border-radius: 4px;
  padding: 40px;
  max-width: 900px;
  margin: 0 auto 32px;
  position: relative;
}

.article-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  flex-wrap: wrap;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.article-meta .cat {
  font-weight: 600;
}

.article-meta .cat--forest { color: var(--forest-court); }
.article-meta .cat--gold { color: var(--champ-gold); }
.article-meta .cat--navy { color: var(--courtside-navy); }
.article-meta .cat--burgundy { color: var(--burgundy-crest); }

.article-meta .dot {
  width: 4px; height: 4px;
  border-radius: 50%;
  background: var(--slate-mist);
  display: inline-block;
}

.article-meta .date {
  color: var(--ink-smoke);
}

.lead-article h3 {
  font-family: var(--font-display);
  font-size: 26px;
  color: var(--courtside-navy);
  margin: 0 0 12px;
  line-height: 1.25;
  font-weight: 700;
}

.lead-article p {
  font-family: var(--font-body);
  font-size: 17px;
  color: var(--ink-smoke);
  line-height: 1.7;
  margin: 0 0 20px;
}

.read-more {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--burgundy-crest);
  font-weight: 600;
}

.read-more:hover { color: var(--champ-gold); }

.article-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}

.article-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 28px;
  box-shadow: 0 2px 12px rgba(27,42,74,0.08);
  transition: all var(--transition);
}

.article-card:hover {
  background: var(--antique-linen);
  box-shadow: var(--shadow-card-hover);
}

.article-card h3 {
  font-family: var(--font-display);
  font-size: 20px;
  color: var(--courtside-navy);
  margin: 0 0 10px;
  font-weight: 700;
  line-height: 1.3;
}

.article-card p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.65;
  margin: 0 0 16px;
}

/* Featured story (news-section-3) */
.featured-story {
  background: var(--antique-linen);
  padding: 96px 0;
  position: relative;
}

.frieze {
  display: block;
  width: 100%;
  height: 44px;
  background-image: url("assets/frieze.svg");
  background-repeat: repeat-x;
  background-size: auto 44px;
  background-position: center;
}

.featured-story .content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
  padding: 24px 32px;
}

.featured-story h2 {
  font-family: var(--font-display);
  font-size: clamp(30px, 4vw, 46px);
  color: var(--courtside-navy);
  margin: 16px 0 18px;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.featured-story .featured-sub {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 19px;
  color: var(--ink-smoke);
  line-height: 1.7;
  max-width: 620px;
  margin: 0 auto 24px;
}

.featured-story .featured-body {
  font-family: var(--font-body);
  font-size: 18px;
  color: var(--courtside-navy);
  line-height: 1.75;
  text-align: left;
  margin: 32px 0;
}

/* Category browse grid */
.category-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  max-width: 960px;
  margin: 0 auto;
}

.category-tile {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 32px;
  position: relative;
  transition: all var(--transition);
  cursor: pointer;
  display: block;
  color: inherit;
}

.category-tile::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--champ-gold);
  border-radius: 4px 4px 0 0;
}

.category-tile:hover {
  background: var(--antique-linen);
  box-shadow: 0 4px 16px rgba(27,42,74,0.15);
  transform: translateY(-2px);
}

.category-tile:hover::before { background: var(--burgundy-crest); }

.category-tile .cat-icon {
  width: 28px; height: 28px;
  color: var(--champ-gold);
  margin-bottom: 18px;
}

.category-tile h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  margin: 0 0 8px;
  font-weight: 700;
}

.category-tile p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--ink-smoke);
  line-height: 1.6;
  margin: 0 0 16px;
}

.cat-count {
  display: inline-block;
  background: var(--antique-linen);
  color: var(--champ-gold);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 600;
  padding: 5px 12px;
  border-radius: 999px;
}

/* ============================================================
   CONTACT PAGE
   ============================================================ */
.contact-block {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: start;
  max-width: 1120px;
  margin: 0 auto;
}

.contact-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.contact-item {
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-radius: 16px;
  padding: 20px 24px;
  display: grid;
  grid-template-columns: 36px 1fr;
  gap: 16px;
  align-items: start;
  transition: all var(--transition);
  position: relative;
}

.contact-item::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: 0;
  width: 0;
  background: var(--burgundy-crest);
  transition: width var(--transition);
  border-radius: 16px 0 0 16px;
}

.contact-item:hover { background: #ddd5bf; }
.contact-item:hover::before { width: 3px; }

.contact-icon {
  width: 28px; height: 28px;
  color: var(--champ-gold);
  margin-top: 4px;
}

.contact-item h4 {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--courtside-navy);
  font-weight: 600;
  margin: 0 0 4px;
}

.contact-item p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.55;
  margin: 0;
}

.map-frame {
  background: var(--antique-linen);
  padding: 14px;
  border: 2px solid var(--champ-gold);
  border-radius: 4px;
  position: relative;
}

.map-frame::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid var(--champ-gold);
  pointer-events: none;
}

.map-frame svg { display: block; width: 100%; height: auto; background: var(--crown-ivory); }

.map-caption {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-smoke);
  text-align: center;
  margin-top: 12px;
}

/* Enquiry feature grid */
.enquiry-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1120px;
  margin: 0 auto;
}

.enquiry-card {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 2px 8px rgba(27,42,74,0.07);
  transition: all var(--transition);
}

.enquiry-card:hover {
  background: var(--antique-linen);
  border-color: var(--champ-gold);
  border-width: 2px;
  padding: 31px;
}

.enquiry-card:hover h3 { color: var(--burgundy-crest); }

.enquiry-badge {
  width: 40px;
  height: 40px;
  margin-bottom: 16px;
  color: var(--champ-gold);
}

.enquiry-card h3 {
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--courtside-navy);
  margin: 0 0 10px;
  font-weight: 700;
  transition: color var(--transition);
}

.enquiry-card p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.65;
  margin: 0 0 16px;
}

.enquiry-email {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--burgundy-crest);
  font-weight: 600;
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}

.enquiry-email:hover {
  color: var(--burgundy-crest);
  border-bottom-color: var(--champ-gold);
}

/* FAQ */
.faq-icons-row {
  display: flex;
  gap: 32px;
  justify-content: center;
  margin-bottom: 36px;
}

.faq-icons-row .seal {
  width: 36px; height: 36px;
  color: var(--champ-gold);
}

.faq-list {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.faq-item {
  background: var(--crown-ivory);
  border: 1px solid var(--slate-mist);
  border-left: 3px solid var(--slate-mist);
  border-radius: 4px;
  overflow: hidden;
  transition: background var(--transition), border-color var(--transition);
}

.faq-item[open] {
  background: var(--antique-linen);
  border-left-color: var(--burgundy-crest);
}

.faq-item summary {
  list-style: none;
  cursor: pointer;
  padding: 18px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-display);
  font-size: 18px;
  color: var(--courtside-navy);
  font-weight: 700;
}

.faq-item summary::-webkit-details-marker { display: none; }

.faq-item summary::after {
  content: "+";
  font-family: var(--font-accent);
  font-size: 22px;
  color: var(--champ-gold);
  font-weight: 400;
  transition: transform var(--transition);
}

.faq-item[open] summary::after { content: "−"; }

.faq-item .answer {
  padding: 0 24px 20px;
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--ink-smoke);
  line-height: 1.7;
  margin: 0;
}

/* ============================================================
   PILLAR / FEATURE GRID generic 3-up (used in feature_grid sections)
   ============================================================ */
.pillar-card {
  text-align: center;
  background: var(--antique-linen);
  border: 1px solid var(--slate-mist);
  border-radius: 4px;
  padding: 40px 32px;
  position: relative;
  box-shadow: var(--shadow-card);
  transition: all var(--transition);
}

.pillar-card:hover {
  background: var(--crown-ivory);
  border-color: var(--champ-gold);
  transform: translateY(-2px);
}

.pillar-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 0;
  background: var(--champ-gold);
  border-radius: 4px 4px 0 0;
  transition: height var(--transition);
}

.pillar-card:hover::before { height: 3px; }

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1100px) {
  .container { padding: 0 40px; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid,
  .testimonial-grid { grid-template-columns: repeat(2, 1fr); }
  .coach-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
  .facility-grid { grid-template-columns: repeat(2, 1fr); }
  .article-grid { grid-template-columns: 1fr; }
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .contact-block { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .fixture-list { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .section { padding: 64px 0; }
  .hero { min-height: 90vh; padding: 80px 20px 60px; }
  .hero-emblem { width: 120px; height: 120px; }
  .hero-headline { font-size: 36px; }
  .hero-sub { font-size: 16px; }
  .stats-grid,
  .feature-grid,
  .testimonial-grid,
  .coach-grid,
  .pricing-grid,
  .facility-grid,
  .category-grid,
  .enquiry-grid { grid-template-columns: 1fr; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }

  .primary-nav {
    display: none;
    position: absolute;
    top: 88px;
    right: 0;
    left: 0;
    background: var(--courtside-navy);
    flex-direction: column;
    padding: 24px;
    gap: 18px;
    border-bottom: 1px solid rgba(184,150,46,0.4);
  }
  .primary-nav.is-open { display: flex; }
  .nav-toggle { display: flex; }

  .timeline::before { left: 16px; transform: none; }
  .timeline-entry,
  .timeline-entry:nth-child(odd),
  .timeline-entry:nth-child(even) {
    width: 100%;
    left: 0;
    text-align: left;
    padding-left: 44px;
    padding-right: 0;
  }
  .timeline-entry:nth-child(odd) .node,
  .timeline-entry:nth-child(even) .node { left: 9px; right: auto; }
  .timeline-entry:nth-child(odd) .connector,
  .timeline-entry:nth-child(even) .connector { left: 16px; right: auto; }

  .chart-row { grid-template-columns: 1fr; gap: 6px; }

  .btn-row { flex-direction: column; align-items: stretch; }
  .btn { width: 100%; }

  .lead-article { padding: 28px; }
  .featured-story .content { padding: 16px 16px; }
  .faq-icons-row { display: none; }
}

